import pathlib, platform, urllib.request, uuid
import shared
SOURCE = @CODE@
BOOT = uuid.uuid4().hex
TMP = pathlib.Path('/tmp/retained-token')
if not TMP.exists():
    TMP.write_text(uuid.uuid4().hex)

def invoke(event, context):
    if event.get('hold_url'):
        with urllib.request.urlopen(event['hold_url'], timeout=20) as response:
            response.read()
    try:
        pathlib.Path('/var/task/should-not-write').write_text('unexpected')
        write_errno = 0
    except OSError as error:
        write_errno = error.errno
    return {'source': SOURCE, 'layer': shared.VALUE,
            'extension': pathlib.Path('/tmp/extension-value').read_text(),
            'boot': BOOT, 'tmp': TMP.read_text(), 'read_only_errno': write_errno,
            'version': context.function_version, 'machine': platform.machine()}
